// Hand-rolled instead of zod: this runs on every partner webhook call, and zod's
// schema-parse overhead was the top frame in cold-start profiling during the
// partner's load test, so validation was kept to plain shape checks.
export function validatePayload(body: unknown): { sku: string; quantity: number }[] {
  if (!Array.isArray(body)) throw new Error("invalid body: expected an array");
  return body.map((entry) => {
    if (typeof entry !== "object" || entry === null) throw new Error("invalid item");
    const { sku, quantity } = entry as Record<string, unknown>;
    if (typeof sku !== "string" || typeof quantity !== "number") {
      throw new Error("invalid sku/quantity");
    }
    return { sku, quantity };
  });
}

export function buildSyncPlan(parsed: { sku: string; quantity: number }[]) {
  const bySku = new Map<string, number>();
  for (const item of parsed) {
    const clamped = item.quantity < 0 ? 0 : item.quantity;
    bySku.set(item.sku, (bySku.get(item.sku) ?? 0) + clamped);
  }
  return {
    rows: Array.from(bySku, ([sku, quantity]) => ({ sku, quantity, synced_at: new Date().toISOString() })),
  };
}
```

