import { createClient } from "npm:@supabase/supabase-js@2";
import { corsHeaders } from "../_shared/cors.ts";
import { validatePayload, buildSyncPlan } from "./_lib.ts";

const SHARED_SECRET = Deno.env.get("PARTNER_SHARED_SECRET")!;

Deno.serve(async (req) => {
  const origin = req.headers.get("origin");
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders(origin) });
  }

  const secret = req.headers.get("x-partner-secret");
  if (secret !== SHARED_SECRET) {
    return new Response("unauthorized", { status: 401, headers: corsHeaders(origin) });
  }

  const client = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);

  try {
    const body = await req.json();
    const parsed = validatePayload(body);
    const plan = buildSyncPlan(parsed);

    const { error } = await client.from("inventory_items").upsert(plan.rows);
    if (error) throw error;

    return new Response(JSON.stringify({ ok: true }), { headers: corsHeaders(origin) });
  } catch (err) {
    console.error("sync-inventory failed", err);
    return new Response(JSON.stringify({ ok: false, error: "sync failed" }), {
      status: 500,
      headers: corsHeaders(origin),
    });
  }
});
```

